const question = $('Form trigger 1').first().json.Question;

const candidates = $input.all().map((item, i) => ({
  index: i,
  text: item.json.document?.pageContent,
  sourceDocument: item.json.document?.metadata?.sourceDocument || 'unknown'
}));

const prompt = `Question: ${question}

Rate each passage's relevance to the question, 0-10. Respond ONLY with a JSON array of integers, same order as given, no other text.

` + candidates.map(c => `[${c.index}] ${c.text}`).join('\n');

return [{ json: { prompt, candidates, question } }];

const raw = $input.first().json.output;
const cleaned = raw.replace(/```json|```/g, '').trim();
let scores;
try { scores = JSON.parse(cleaned); } catch { scores = []; }

const candidates = $('Format candidates for reranking').first().json.candidates;
const ranked = candidates
  .map((c, i) => ({ ...c, relevance: scores[i] ?? 0 }))
  .sort((a, b) => b.relevance - a.relevance)
  .slice(0, 5);

return [{
  json: {
    question: $('Format candidates for reranking').first().json.question,
    ranked
  }
}];

const { question, ranked } = $input.first().json;

const context = ranked
  .map(r => `[Source: ${r.sourceDocument}] ${r.text}`)
  .join('\n\n');

const prompt = `Question: ${question}

Passages:
${context}`;

return [{ json: { question, ranked, answerPrompt: prompt } }];
